/**
 * Log
 *
 * ChurchTools writes log messages for many events and changes. This can be an update for a person or the deletion of an event. You can use the log to debug your system and follow error messages. This is a versitile tool.
 */
export type Log = {
    /**
     * Timestamp of log
     */
    date: string;
    /**
     * Analog to the domain type, the ID is the explicit resource.
     */
    domainId: number;
    /**
     * The domain type tells us, where in ChurchTools the action was performed.
     */
    domainType: string;
    id: number;
    /**
     * The log level indicates the importance. 1 = Warning, 2 = Notice, 3 = Info.
     */
    level: number;
    message: string;
    person?: DomainObjectPerson | null;
    /**
     * If the person ID is `-1`, that means, no person but the system itself has logged that message.
     */
    personId: number;
    /**
     * The name of the person, who caused the log message. This is stored in the log, because the person could be deleted later. So we have the name in the log, even if the person is deleted.
     */
    personName: string;
    simulatePerson: DomainObjectPerson | null;
    /**
     * If a person is simulated by an administrator, we log the personId as well. This makes it possible to see if a person did the action or an admin, who simulated that person.
     */
    simulatePersonId: number | null;
};

/**
 * Markdown Conversion Request
 *
 * Schema for validating markdown conversion requests
 */
export type MarkdownRequest = {
    /**
     * Global options for all sources
     */
    options?: {
        commonLanguage?: string;
        defaultOutputScope?: 'plaintext' | 'richline' | 'description' | 'document';
    };
    sources: Array<{
        /**
         * The scope of the input content
         */
        inputScope: 'plaintext' | 'richline' | 'description' | 'document';
        /**
         * The markdown content to be processed
         */
        markdown: string;
        /**
         * Additional processing options
         */
        options?: {
            allowHtml?: boolean;
            language?: string;
            maxLength?: number;
        };
        /**
         * List of output formats for the processed markdown content
         */
        outputFormats: Array<'html' | 'md' | 'xml'>;
        /**
         * List of scopes for the output content
         */
        outputScopes: Array<'plaintext' | 'richline' | 'description' | 'document'>;
        /**
         * A short identifier for the source
         */
        shortName: string;
    }>;
};

